/* v5: redesign only, local synthetic interactions; Analysis remains untouched. */
const priorTodayV5=today, priorGoalsV5=goals, priorPersonalV5=personal, priorRenderV5=render, priorActionV5=action;
const sumMinutesV5=rs=>rs.reduce((n,r)=>n+r.minutes,0);
const sectionV5=(label,tail='')=>`<div class="section-v5"><strong>${label}</strong>${tail}</div>`;
const linkV5=(label,a)=>V4(label+icon('chevron'),a,'text-link-v5');
function todayActualV5(){return recs().filter(r=>r.date==='2026-11-05')}
today=function(){
 const available=scenario!=='first'&&scenario!=='error', actual=todayActualV5(), last=recs()[0];
 return `${status().replace('9:41','9:20')}<div class="screen-content today-v5">
 <header class="context-v5"><div class="date-tile-v5 glass"><small>NOV</small><b>05</b></div><div class="context-copy-v5"><strong>周四 · 上午</strong><span>2026 年 11 月</span></div><button class="context-icon-v5 glass" data-v4="records" aria-label="查看执行记录">${icon('clock')}</button></header>
 <button class="quick-entry-v5 glass" data-v4="capture">${icon('edit')}<span>记下刚刚做过的事…</span><i>${icon('plus')}</i></button>
 <div class="day-ledger-v5"><button data-v4="today-schedule"><strong>${scenario==='error'?'—':available?'3':'0'}<small>项安排</small></strong><span>${scenario==='error'?'尚未读取':available?'105 分钟 · 计划量':'还没有安排'}</span></button><div></div><button data-v4="records"><strong>${scenario==='error'?'—':actual.length}<small>条执行</small></strong><span>${scenario==='error'?'尚未读取':sumMinutesV5(actual)+' 分钟 · 今日实际'}</span></button></div>
 ${available?`<section class="next-v5 glass"><div class="next-top-v5"><span><i></i>接下来</span><button data-v4="plan:prototype">09:30–10:15 ${icon('arrow')}</button></div><div class="next-object-v5"><span class="crystal-icon-v5">${icon('cube')}</span><div><h3>原型设计</h3><p>完成作品集项目 / 问题与方案</p></div><span class="duration-v5">45<small>分钟</small></span></div><div class="next-relations-v5"><span>关联方向</span><button data-v4="goal">完成作品集项目 ${icon('chevron')}</button></div><button class="glass-action-v5" data-v4="capture:prototype">${icon('plus')}记录实际执行${icon('arrow')}</button></section>`:empty(scenario==='error'?'暂时无法读取今日安排':'今天，从一件事开始',scenario==='error'?'读取未完成，不能判断今天是否有安排。':'先安排一项行动，或记录已经发生的事。','calendar',scenario==='error'?'retry':'new-plan',scenario==='error'?'重试读取':'安排一件事')}
 ${sectionV5('后续安排',linkV5('完整日程','today-schedule'))}
 <section class="later-v5">${available?[['reading','book','阅读与笔记',readingMoved?'14:30':'14:00',readingMoved?'15:00':'14:30','保持阅读'],['walk','walk','散步','17:30','18:00','让活动融入日常']].map(([id,ic,n,t,end,g])=>`<button class="later-row-v5" data-v4="plan:${id}"><time>${t}<small>${end}</small></time><span class="agenda-dot-v5 ${id}"></span><div><strong>${n}</strong><span>${g}</span></div><small>30 分钟</small>${icon('chevron')}</button>`).join(''):`<p class="quiet-copy-v5">${scenario==='error'?'等待重新读取。':'安排会显示在这里，计划与实际记录分别保留。'}</p>`}</section>
 <button class="state-strip-v5 glass" data-v4="state">${icon('filter')}<span><strong>此刻精力</strong><small>${localStatus?'已记录这次自评':'按当下感受记录'}</small></span><b>${localStatus?localStatus+' / 5':'未记录'}</b>${icon('chevron')}</button>
 ${sectionV5('最近执行',linkV5('全部记录','records'))}
 ${last?`<button class="recent-v5" data-v4="record:${last.id}"><span class="record-mark-v5">${icon('doc')}</span><div><strong>${esc(last.skill)} <small>${last.minutes} 分钟</small></strong><p>${esc(last.note)}</p><time>${last.date.replaceAll('-','.')} · ${last.time}</time></div>${icon('chevron')}</button>`:'<p class="quiet-copy-v5">实际记录会保留内容、时间与关联，不把计划计为完成。</p>'}
 </div>${nav(0)}`;
};
goals=function(){
 const unavailable=['first','error'].includes(scenario), ss=skillsV4.filter(s=>s.target==='完成作品集项目'), rs=recs().filter(r=>ss.some(s=>s.name===r.skill));
 let main='';
 if(scenario==='error')main=empty('目标暂时未能读取','列表加载失败，已有目标不会被当作空列表。','warning','retry','重试读取');
 else if(scenario==='first')main=extraGoals.length?'':empty('给一个方向，定义结果','先确定想达成什么，再关联需要练习的技能。','target','new-goal','创建目标');
 else if(goalFilter==='completed')main=empty('尚无已确认完成的目标','检查结果与证据后再确认完成；执行时长不换算成完成比例。','check','goal-conditions','查看完成依据');
 else main=`<section class="project-v5 glass"><div class="project-tag-v5"><span>${icon('target')}项目方向</span><button data-action="goal-conditions">完成条件待确认 ${icon('chevron')}</button></div><button class="project-name-v5" data-v4="goal"><h3>完成作品集项目</h3>${icon('arrow')}</button><p class="project-description-v5">把一个问题，做成可讲清楚的方案。</p><div class="result-lines-v5"><button data-action="goal-conditions">${icon('circle')}<span>形成可讲解的项目方案</span><small>待确认</small></button><button data-action="goal-conditions">${icon('circle')}<span>完成反馈走查并记录修改</span><small>待确认</small></button></div><div class="project-paths-v5">${[['discovery','nodes','问题与方案'],['delivery','doc','表达与验证']].map(([id,ic,n],i)=>`<button data-v4="module:${id}"><span class="path-marker-v5">${icon(ic)}<small>0${i+1}</small></span><strong>${n}${icon('chevron')}</strong><p>${ss.filter(s=>s.module===n).map(s=>esc(s.name)).join(' · ')}</p></button>`).join('')}</div><div class="project-evidence-v5"><button data-v4="records">${icon('doc')}${rs.length} 次执行 · ${sumMinutesV5(rs)} 分钟${icon('chevron')}</button><span>2 个模块 / ${ss.length} 个技能</span></div></section><button class="next-skill-v5" data-v4="skill:prototype"><span class="small-cube-v5">${icon('cube')}</span><div><small>下一次计划 · 今天 09:30</small><strong>原型设计</strong></div><span>45 分钟</span>${icon('chevron')}</button>
 ${sectionV5('持续方向','<span>各自保留计划与记录</span>')}<section class="directions-v5 glass">${vRow('book','保持阅读','今天 '+(readingMoved?'14:30':'14:00')+' · 阅读与笔记','30 分钟','reading-direction')}${vRow('walk','让活动融入日常','今天 17:30 · 散步','30 分钟','walking-direction')}</section>`;
 return `${status()}<div class="screen-content goals-v5"><header class="context-v5 goal-context-v5"><div class="context-copy-v5"><strong>${unavailable?scenario==='first'?extraGoals.length+' 个方向':'方向尚未读取':3+extraGoals.length+' 个方向'}</strong><span>${unavailable?'结果 → 路径 → 执行':skillsV4.length+' 个关联技能 · 独立保留执行证据'}</span></div><button class="context-icon-v5 glass" data-action="goal-search" aria-label="查找目标">${icon('search')}</button><button class="context-icon-v5 glass" data-action="new-goal" aria-label="新增目标">${icon('plus')}</button></header><div class="segment"><button data-action="goal-all" class="${goalFilter==='all'?'active':''}">全部方向</button><button data-action="goal-active" class="${goalFilter==='active'?'active':''}">进行中</button><button data-action="goal-completed" class="${goalFilter==='completed'?'active':''}">已完成</button></div>${main}${extraGoals.map((g,i)=>`<div class="directions-v5 glass">${row('target',esc(g.name),'尚未关联模块与技能','新建','created-goal-'+i)}</div>`).join('')}<section class="library-v5 glass"><button class="library-intro-v5" data-v4="library"><span class="library-icon-v5">${icon('folder')}</span><div><strong>技能库</strong><p>积累做过的事，复用已有技能</p></div>${icon('arrow')}</button><div class="library-links-v5">${V4(icon('nodes')+'研究与理解','library:research')}${V4(icon('cube')+'设计与表达','library:design')}${V4(icon('plus'),'skill-new')}</div></section></div>${nav(1)}`;
};
personal=function(){return priorPersonalV5().replace(head('个人',btn('info','about','glass')),'').replace('<p class="profile-version">QuestLife · 个人空间</p>','<button class="profile-version v5-about" data-action="about">QuestLife · 关于与版本 '+icon('chevron')+'</button>')};
const baseHandleV5=handleV4;
handleV4=function(phone,a){if(a==='reading-direction'){action(phone,'reading-goal');return}if(a==='walking-direction'){action(phone,'activity-goal');return}if(a==='library:research'||a==='library:design'){v4Filter=a.endsWith('research')?'研究与理解':'设计与表达';navigateV4(phone.id,'library');return}baseHandleV5(phone,a)};
render=function(){priorRenderV5();const ss=document.querySelector('#schedule>.status>span');if(ss)ss.textContent='9:20';document.querySelectorAll('.board-title span').forEach((s,i)=>s.textContent=['行动 / 安排 / 实际记录','结果条件 / 路径 / 技能','顶部收紧 · 保留原布局','本轮完全保留','内容上提 · 保留原结构'][i]);};
render();

// Search keeps its input handler when rendered as a full page.
const priorRouteV5=routeV4;
routeV4=function(key,route){if(route==='goal-search-v5'){const dirs=scenario==='error'?[]:[...(scenario==='first'?[]:[{name:'完成作品集项目',sub:'问题与方案 / 表达与验证',ic:'target',a:'goal-detail'},{name:'保持阅读',sub:'阅读与笔记',ic:'book',a:'reading-goal'},{name:'让活动融入日常',sub:'散步',ic:'walk',a:'activity-goal'}]),...extraGoals.map((g,i)=>({name:g.name,sub:'尚未关联模块与技能',ic:'target',a:'created-goal-'+i}))];return{title:'查找方向',body:`<label class="child-search glass">${icon('search')}<input id="goal-query-v5" aria-label="查找目标或技能" placeholder="查找方向或关联技能"></label><section class="child-list glass">${dirs.map(d=>`<div data-query="${esc(d.name+d.sub)}">${row(d.ic,esc(d.name),esc(d.sub),'',d.a)}</div>`).join('')}</section><p class="notice search-empty-v5" hidden>没有匹配的方向，试试其他名称。</p>`,bind:n=>{const input=n.querySelector('#goal-query-v5'),items=[...n.querySelectorAll('[data-query]')];const apply=()=>{items.forEach(e=>e.hidden=!e.dataset.query.includes(input.value));n.querySelector('.search-empty-v5').hidden=items.some(e=>!e.hidden)};input.addEventListener('input',apply);apply()}}}return priorRouteV5(key,route)};
action=function(phone,a){if(a==='goal-search'){navigateV4(phone.id,'goal-search-v5');return}priorActionV5(phone,a)};
render();
